 10→class LruBlockCacheTest {
 11→
 12→    // --- Builder ---
 13→
 14→    @Test
 15→    void zeroCapacityRejected() {
 16→        assertThrows(IllegalArgumentException.class,
 17→                () -> LruBlockCache.builder().capacity(0).build());
 18→    }
 19→
 20→    @Test
 21→    void negativeCapacityRejected() {
 22→        assertThrows(IllegalArgumentException.class,
 23→                () -> LruBlockCache.builder().capacity(-1).build());
 24→    }
 25→
 26→    // --- get / put ---
 27→
 28→    @Test
 29→    void getMissOnEmptyCacheReturnsEmpty() {
 30→        try (var cache = LruBlockCache.builder().capacity(10).build()) {
 31→            assertTrue(cache.get(1L, 0L).isEmpty());
 32→        }
 33→    }
 34→
 35→    @Test
 36→    void putThenGetReturnsBlock() {
 37→        try (var cache = LruBlockCache.builder().capacity(10).build()) {
 38→            var block = MemorySegment.ofArray(new byte[]{ 1, 2, 3 });
 39→            cache.put(1L, 0L, block);
 40→            assertEquals(block, cache.get(1L, 0L).orElseThrow());
 41→        }
 42→    }
 43→
 44→    @Test
 45→    void getWrongSstableIdMisses() {
 46→        try (var cache = LruBlockCache.builder().capacity(10).build()) {
 47→            cache.put(1L, 0L, MemorySegment.ofArray(new byte[]{ 1 }));
 48→            assertTrue(cache.get(2L, 0L).isEmpty());
 49→        }
 50→    }
 51→
 52→    @Test
 53→    void getWrongOffsetMisses() {
 54→        try (var cache = LruBlockCache.builder().capacity(10).build()) {
 55→            cache.put(1L, 0L, MemorySegment.ofArray(new byte[]{ 1 }));
 56→            assertTrue(cache.get(1L, 1L).isEmpty());
 57→        }
 58→    }
 59→
 60→    @Test
 61→    void putOverwritesExistingEntry() {
